local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/Action/ActionDarkDreamRewardPopup.prefab > name: Cell
---@class ActionDarkDreamRewardPopupCell
---@field Env                           	ActionDarkDreamRewardPopupCell          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgDecorate                   	UnityEngine.RectTransform               
---@field TxtNum                        	UnityEngine.RectTransform               
---@field Underway                      	UnityEngine.RectTransform               
---@field FontStyleButton               	Game.Native.Common.FontStyleButton      
---@field Finish                        	UnityEngine.RectTransform               
---@field UIFX_ActivityCompletion       	UnityEngine.RectTransform               
---@field CommonGoodsList               	Engine.Lib.GOPoolBehaviour              
---@field AnimRoot                      	UnityEngine.RectTransform               
local ActionDarkDreamRewardPopupCell = Class('ActionDarkDreamRewardPopupCell')
function ActionDarkDreamRewardPopupCell:__init()
    self.callBack = nil
end

function ActionDarkDreamRewardPopupCell:__delete()
    self.callBack = nil
end

function ActionDarkDreamRewardPopupCell:Awake()
    SetButtonAction(self.FontStyleButton,Bind(self,self.OnBtnGetClick))
end

function ActionDarkDreamRewardPopupCell:SetCallBack(callBack)
    self.callBack = callBack
end

function ActionDarkDreamRewardPopupCell:RefreshShow(data,isGet,curStar)
    if isNull(data) then return end
    self.data = data
    self.isGet = isGet
    KTool.SetActive(self.Finish.gameObject,isGet)
    if isGet then
        KTool.SetActive(self.Underway.gameObject,false)
        KTool.SetActive(self.FontStyleButton.gameObject,false)
        CfUtils.SetUISwitchImage(self.ImgDecorate,1)
    else
        local isCanGet = curStar >= self.data.starLevel
        self.isCanGet = isCanGet
        KTool.SetActive(self.Underway.gameObject,not isCanGet)
        KTool.SetActive(self.FontStyleButton.gameObject,isCanGet)

        local status = isCanGet and 2 or 1
        CfUtils.SetUISwitchImage(self.ImgDecorate,status)
    end
    CfUtils.FillText(self.TxtNum,data.starLevel)

    self:FillReward()
end

function ActionDarkDreamRewardPopupCell:FillReward()
    ---@type CommonGoodsListLight
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsListLight")
    scr:FreshBaseUI(self.data.rewards)
end

function ActionDarkDreamRewardPopupCell:OnBtnGetClick()
    if not self.isGet then
        if self.isCanGet then
            self.callBack(self.data.starLevel)
        else
            GameUtils.Toast(localize("未满足条件"))
        end
    else
        GameUtils.Toast(localize("该奖励已领取"))
    end
end

function ActionDarkDreamRewardPopupCell:PlayAnimByShowed()
    CfUtils.PlayAnimator(self.AnimRoot, "Go")
end


function ActionDarkDreamRewardPopupCell:PlayAnimByEnter(delayIndex)
    CfUtils.PlayAnimator(self.AnimRoot, "Wait")
    CfUtils.PlayDelayShowAnimate(self.AnimRoot, checkInt(delayIndex), 0.1)
end

function ActionDarkDreamRewardPopupCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamRewardPopupCell